/**
 * Proves Task 18's photo write path — the bytes, then the rows.
 *
 * Two halves, deliberately apart, because they answer two different questions:
 *
 *   * **the bytes.** A real image is generated here carrying EXIF, run through the same
 *     `preparePhoto` the Server Action runs, and put in the asset store with the same `uploadImage`.
 *     "EXIF is stripped at the write boundary" is then *measured*: the EXIF segment is present in the
 *     generated bytes and absent from the prepared ones, and the asset the store holds is exactly
 *     `prepared.bytes.length` bytes — so what was uploaded is what was prepared. The throwaway asset
 *     is deleted again in a `finally`, so a run leaves the dataset as it found it.
 *
 *   * **the rows.** `carCreateStatement` and `carUpdateStatement` run against the live store inside
 *     one transaction that is rolled back: photos land in position order; an existing photo keeps the
 *     source it was stored with while a new one becomes an owner upload; a reorder is a real write;
 *     a removal deletes the surplus row; and a repeated call is a true no-op (no version bump, no
 *     second event), which is the idempotence the store guard's retries lean on (D18).
 *
 *   node --dns-result-order=ipv4first --import tsx developer-workspace/scripts/task-004/photo-write-check.ts
 */
import { config as loadEnv } from "dotenv";
import { Client } from "pg";
import sharp from "sharp";
import { readCarInput } from "../../../lib/car-input";
import { carCreateStatement } from "../../../lib/car-create";
import { carUpdateStatement } from "../../../lib/car-update";
import { carChangeCheck, CHANGE_CHECK_VERSION } from "../../../lib/change-check";
import { preparePhoto } from "../../../lib/photos";
import { isAssetRef } from "../../../lib/photo-rules";
import { deleteAsset, findImageAsset, imageUrl, uploadImage } from "../../../lib/sanity";

loadEnv({ path: ".env.local", quiet: true });

let failures = 0;
function ok(label: string, pass: boolean, detail = "") {
  console.log(`  ${pass ? "PASS" : "FAIL"}  ${label}${detail ? ` — ${detail}` : ""}`);
  if (!pass) failures++;
}

/** The EXIF signature — the thing that must not survive the write boundary. */
const EXIF = Buffer.from("Exif\0\0", "latin1");

async function bytesHalf() {
  console.log("\nthe bytes — a real photo, carrying EXIF, through the boundary the action uses");

  const jpeg = await sharp({
    create: { width: 64, height: 48, channels: 3, background: { r: 20, g: 90, b: 160 } },
  })
    .jpeg({ quality: 88 })
    .withMetadata({ exif: { IFD0: { ImageDescription: "witness — where I was that afternoon" } } })
    .toBuffer();

  // The control. A check that only ever says "no EXIF" proves nothing unless the thing it looks for
  // can be present at all.
  ok("the generated photo really carries EXIF", jpeg.includes(EXIF), `${jpeg.length} bytes`);

  const prepared = preparePhoto(jpeg, "image/jpeg");
  if (!prepared.ok) throw new Error(`preparePhoto refused the witness photo: ${prepared.reason}`);
  ok("preparePhoto says it stripped metadata", prepared.stripped);
  ok("no EXIF survives into the bytes to store", !prepared.bytes.includes(EXIF));
  ok(
    "the image is not re-encoded — only the metadata left",
    prepared.bytes.length < jpeg.length,
    `${jpeg.length} → ${prepared.bytes.length} bytes`,
  );

  let assetId: string | null = null;
  try {
    const uploaded = await uploadImage(prepared.bytes, {
      filename: "witness-photo.jpg",
      contentType: "image/jpeg",
    });
    assetId = uploaded.assetId;

    ok("the store hands back a reference, not an address", isAssetRef(uploaded.assetId), uploaded.assetId);
    const found = await findImageAsset(uploaded.assetId);
    ok("the reference resolves back to a stored asset", found !== null, found ? `${found.size} bytes` : "nothing found");
    ok(
      "the store holds exactly the prepared (stripped) bytes",
      found?.size === prepared.bytes.length,
      `${found?.size} vs ${prepared.bytes.length}`,
    );
    const url = imageUrl(uploaded.assetId);
    ok(
      "an address is derivable from it on demand, and is stored nowhere",
      url.startsWith("https://cdn.sanity.io/images/"),
      url,
    );
  } finally {
    if (assetId) {
      const gone = await deleteAsset(assetId);
      ok("the proof's own asset is removed again", gone.deleted, gone.reason ?? "");
    }
  }
}

const A = "image-witnessaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa-1200x800-jpg";
const B = "image-witnessbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb-800x600-png";
const C = "image-witnesscccccccccccccccccccccccccccccccc-640x480-webp";

async function rowsHalf() {
  console.log("\nthe rows — the same statements the actions run, in a transaction that is rolled back");

  const connectionString = process.env.DATABASE_URL_UNPOOLED ?? process.env.DATABASE_URL;
  if (!connectionString) throw new Error("DATABASE_URL is not set");
  const client = new Client({ connectionString });
  await client.connect();

  try {
    const primary = (
      await client.query<{ id: string }>("SELECT id FROM car_state WHERE kind='primary' AND label='Available'")
    ).rows[0];

    await client.query("BEGIN");

    const actor = (
      await client.query<{ id: string }>(
        "INSERT INTO office_user (email) VALUES ('photo-check@truespec.local') RETURNING id",
      )
    ).rows[0].id;

    const read = readCarInput({
      brand: "Check",
      model: "Photos",
      trim: "T1",
      year: "2023",
      exteriorColor: "Blue",
      interiorColor: "Grey",
      mileage: "100",
      features: "",
      price: "15,000,000",
      wasPrice: "",
      privateNote: "",
      note: "",
      arrivalNote: "",
      stateId: primary.id,
      secondaryStateIds: [],
      costs: { purchase_price: "10,000,000" },
    });
    if (!read.ok) throw new Error(`witness form refused: ${JSON.stringify(read.errors)}`);
    const { columns } = read.value;

    const id = "22222222-2222-4222-8222-222222222222";
    const createStmt = carCreateStatement({
      id,
      columns,
      costs: read.value.costs,
      secondaryStateIds: read.value.secondaryStateIds,
      photos: [A, B],
      contentHash: carChangeCheck(columns as unknown as Record<string, unknown>),
      hashVersion: CHANGE_CHECK_VERSION,
      actorId: actor,
    });
    const created = await client.query<{ ref: string }>(createStmt.text, createStmt.params);
    const ref = created.rows[0]?.ref ?? "";
    ok("a car is made and a ref returned", /^TS-\d{4}$/.test(ref), ref);

    const stored = async () =>
      (
        await client.query<{ sanity_asset_id: string; position: number; origin: string }>(
          "SELECT sanity_asset_id, position, origin FROM car_photo WHERE car_id=$1 ORDER BY position",
          [id],
        )
      ).rows;

    let rows = await stored();
    ok("the photos are stored in the order they arrived", rows.map((r) => r.sanity_asset_id).join(",") === `${A},${B}`);
    ok("position is the order — the cover is 0", rows[0]?.position === 0 && rows[1]?.position === 1, rows.map((r) => r.position).join(","));
    ok("a new car's photos are owner uploads", rows.every((r) => r.origin === "owner upload"));

    // A row that came from somewhere else (the rebuild left rows with a non-owner source). The
    // update must not relabel it just because it was saved again.
    await client.query("UPDATE car_photo SET origin='unsplash:legacy' WHERE car_id=$1 AND sanity_asset_id=$2", [id, B]);

    const versionBefore = Number((await client.query("SELECT version FROM car WHERE id=$1", [id])).rows[0].version);

    const updateArgs = (photos: string[], hash: string) => ({
      id,
      columns,
      costs: read.value.costs,
      secondaryStateIds: read.value.secondaryStateIds,
      photos,
      sale: null,
      contentHash: hash,
      hashVersion: CHANGE_CHECK_VERSION,
      actorId: actor,
    });
    const hash = carChangeCheck(columns as unknown as Record<string, unknown>);
    const run = async (photos: string[]) => {
      const s = carUpdateStatement(updateArgs(photos, hash));
      return client.query(s.text, s.params);
    };

    // --- a reorder, plus one new photo ---
    await run([B, A, C]);
    rows = await stored();
    ok(
      "a reorder rewrites positions, and a new photo is appended",
      rows.map((r) => `${r.sanity_asset_id}@${r.position}`).join(" ") === `${B}@0 ${A}@1 ${C}@2`,
      rows.map((r) => `${r.sanity_asset_id}@${r.position}`).join(" "),
    );
    ok("the stored source survives a re-save", rows[0]?.origin === "unsplash:legacy", rows[0]?.origin);
    ok("only the photo the car did not have becomes an owner upload", rows[2]?.origin === "owner upload", rows[2]?.origin);

    const versionAfter = Number((await client.query("SELECT version FROM car WHERE id=$1", [id])).rows[0].version);
    ok("a photo change is a real write", versionAfter > versionBefore, `${versionBefore} → ${versionAfter}`);

    // --- removing one deletes the row it vacated ---
    await run([B, A]);
    rows = await stored();
    ok("removing a photo deletes its row, leaving no gap", rows.length === 2 && rows[1]?.position === 1, `${rows.length} rows`);

    // --- the same call again is a true no-op (what a retry is) ---
    const eventsBefore = Number(
      (await client.query("SELECT count(*) FROM activity_event WHERE subject=$1", [ref])).rows[0].count,
    );
    const vBefore = Number((await client.query("SELECT version FROM car WHERE id=$1", [id])).rows[0].version);
    await run([B, A]);
    const eventsAfter = Number(
      (await client.query("SELECT count(*) FROM activity_event WHERE subject=$1", [ref])).rows[0].count,
    );
    const vAfter = Number((await client.query("SELECT version FROM car WHERE id=$1", [id])).rows[0].version);
    ok("a repeated save moves nothing", vAfter === vBefore, `version ${vBefore} → ${vAfter}`);
    ok("a repeated save writes no second event", eventsAfter === eventsBefore, `${eventsBefore} → ${eventsAfter}`);

    await client.query("ROLLBACK");
    console.log("  (rolled back — the store is unchanged)");
    const after = Number((await client.query("SELECT count(*) FROM car WHERE id=$1", [id])).rows[0].count);
    ok("the store holds no trace after rollback", after === 0);
  } finally {
    await client.end();
  }
}

async function main() {
  await bytesHalf();
  await rowsHalf();
  console.log(failures === 0 ? "\nPHOTO-WRITE CHECK PASSED" : `\nPHOTO-WRITE CHECK FAILED (${failures})`);
  process.exit(failures === 0 ? 0 : 1);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
